class Solution {
public:
    string originalDigits(string s) {
        vector<int> count(26, 0);
        for (char ch : s) count[ch - 'a']++;
        vector<int> out(10, 0);
        out[0] = count['z' - 'a'];
        out[2] = count['w' - 'a'];
        out[4] = count['u' - 'a'];
        out[6] = count['x' - 'a'];
        out[8] = count['g' - 'a'];
        out[3] = count['h' - 'a'] - out[8];
        out[5] = count['f' - 'a'] - out[4];
        out[7] = count['s' - 'a'] - out[6];
        out[1] = count['o' - 'a'] - out[0] - out[2] - out[4];
        out[9] = count['i' - 'a'] - out[5] - out[6] - out[8];
        string res = "";
        for (int d = 0; d < 10; d++) {
            res.append(out[d], '0' + d);
        }
        return res;
    }
};

class Solution {
    public String originalDigits(String s) {
        int[] count = new int[26];
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
        }
        int[] out = new int[10];
        out[0] = count['z' - 'a'];
        out[2] = count['w' - 'a'];
        out[4] = count['u' - 'a'];
        out[6] = count['x' - 'a'];
        out[8] = count['g' - 'a'];
        out[3] = count['h' - 'a'] - out[8];
        out[5] = count['f' - 'a'] - out[4];
        out[7] = count['s' - 'a'] - out[6];
        out[1] = count['o' - 'a'] - out[0] - out[2] - out[4];
        out[9] = count['i' - 'a'] - out[5] - out[6] - out[8];
        StringBuilder res = new StringBuilder();
        for (int d = 0; d < 10; d++) {
            for (int k = 0; k < out[d]; k++) {
                res.append(d);
            }
        }
        return res.toString();
    }
}

var originalDigits = function(s) {
    const count = new Array(26).fill(0);
    for (let i = 0; i < s.length; i++) {
        count[s.charCodeAt(i) - 97]++;
    }
    const out = new Array(10).fill(0);
    out[0] = count[25]; // z
    out[2] = count[22]; // w
    out[4] = count[20]; // u
    out[6] = count[23]; // x
    out[8] = count[6];  // g
    out[3] = count[7] - out[8]; // h
    out[5] = count[5] - out[4]; // f
    out[7] = count[18] - out[6]; // s
    out[1] = count[14] - out[0] - out[2] - out[4]; // o
    out[9] = count[8] - out[5] - out[6] - out[8]; // i
    let res = "";
    for (let d = 0; d < 10; d++) {
        res += String(d).repeat(out[d]);
    }
    return res;
};
